package com.agacostays.payroll.controller; import com.agacostays.payroll.dto.request.StaffBankAccountRequest;import com.agacostays.payroll.dto.response.*;import com.agacostays.payroll.security.CurrentUserProvider;import com.agacostays.payroll.service.StaffBankAccountService;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;@RestController public class StaffBankAccountController{final StaffBankAccountService s;final CurrentUserProvider c;public StaffBankAccountController(StaffBankAccountService s,CurrentUserProvider c){this.s=s;this.c=c;}@PostMapping("/api/manager/payroll/staff/{staffId}/bank-account") public ResponseEntity<ApiResponse<StaffBankAccountResponse>> add(@PathVariable Long staffId,@Valid @RequestBody StaffBankAccountRequest r){return ResponseEntity.ok(ApiResponse.ok("Bank account saved",s.save(staffId,r,c.userId())));}@GetMapping("/api/manager/payroll/staff/{staffId}/bank-account") public ResponseEntity<ApiResponse<StaffBankAccountResponse>> get(@PathVariable Long staffId){return ResponseEntity.ok(ApiResponse.ok("Bank account fetched",s.get(staffId)));}@PutMapping("/api/manager/payroll/staff/{staffId}/bank-account") public ResponseEntity<ApiResponse<StaffBankAccountResponse>> update(@PathVariable Long staffId,@Valid @RequestBody StaffBankAccountRequest r){return ResponseEntity.ok(ApiResponse.ok("Bank account updated",s.update(staffId,r,c.userId())));}@DeleteMapping("/api/manager/payroll/staff/{staffId}/bank-account") public ResponseEntity<ApiResponse<Void>> delete(@PathVariable Long staffId){s.deactivate(staffId);return ResponseEntity.ok(ApiResponse.ok("Bank account deactivated",null));}@PostMapping("/api/staff/bank-account") public ResponseEntity<ApiResponse<StaffBankAccountResponse>> selfAdd(@Valid @RequestBody StaffBankAccountRequest r){Long id=c.userId();return ResponseEntity.ok(ApiResponse.ok("Bank account saved",s.save(id,r,id)));}@GetMapping("/api/staff/bank-account") public ResponseEntity<ApiResponse<StaffBankAccountResponse>> selfGet(){return ResponseEntity.ok(ApiResponse.ok("Bank account fetched",s.get(c.userId())));}}
